app.MapGet("/invoices/{id:int}", async (int id, BillingDb db) =>
{
    // Logged in, so any invoice id is accepted
    var invoice = await db.Invoices.FindAsync(id);
    return invoice is null ? Results.NotFound() : Results.Ok(invoice);
}).RequireAuthorization();

app.MapGet("/invoices/{id:int}", async (
    int id, ClaimsPrincipal user, BillingDb db) =>
{
    // The tenant comes from the signed-in user, never from the request
    var tenantId = user.FindFirstValue("tenant_id");
    var invoice = await db.Invoices.SingleOrDefaultAsync(
        i => i.Id == id && i.TenantId == tenantId);
    // Another tenant's invoice and a missing one get the same 404
    return invoice is null ? Results.NotFound() : Results.Ok(invoice);
}).RequireAuthorization();
